insert into public.events(id,slug,name_kn,name_en,start_date,end_date,place,district,organiser,description_kn,is_seed) values('00000000-0000-4000-8000-000000000102','seed-study-circle','ಅಹಿಂಸೆ ಮತ್ತು ಜೀವನಮೌಲ್ಯಗಳ ಚಿಂತನೆ','Ahimsa study circle','2026-09-30','2026-09-30','ಬೆಂಗಳೂರು','ಬೆಂಗಳೂರು','ಜ್ವಾಲಾಮಾಲಾ ಸಮುದಾಯ — ಮಾದರಿ','ಇದು ಕ್ಯಾಲೆಂಡರ್ ಪ್ರದರ್ಶನಕ್ಕಾಗಿ ಸೇರಿಸಿದ ಮಾದರಿ ಕಾರ್ಯಕ್ರಮ. ಇದು ನೈಜ ಕಾರ್ಯಕ್ರಮದ ಆಹ್ವಾನವಲ್ಲ.',true) on conflict(id) do nothing;
insert into public.events(id,slug,name_kn,name_en,start_date,end_date,place,district,organiser,description_kn,is_seed) values('00000000-0000-4000-8000-000000000103','seed-youth-forum','ಯುವಜನರ ಸೇವಾ ವೇದಿಕೆ','Youth service forum','2026-10-04','2026-10-04','ಮೈಸೂರು','ಮೈಸೂರು','ಜ್ವಾಲಾಮಾಲಾ ಸಮುದಾಯ — ಮಾದರಿ','ಇದು ಕ್ಯಾಲೆಂಡರ್ ಪ್ರದರ್ಶನಕ್ಕಾಗಿ ಸೇರಿಸಿದ ಮಾದರಿ ಕಾರ್ಯಕ್ರಮ. ಇದು ನೈಜ ಕಾರ್ಯಕ್ರಮದ ಆಹ್ವಾನವಲ್ಲ.',true) on conflict(id) do nothing;
insert into public.events(id,slug,name_kn,name_en,start_date,end_date,place,district,organiser,description_kn,is_seed) values('00000000-0000-4000-8000-000000000104','seed-festival','ಸಾಂಸ್ಕೃತಿಕ ಉತ್ಸವ','Cultural festival','2026-10-10','2026-10-12','ಕಾರ್ಕಳ','ಉಡುಪಿ','ಜ್ವಾಲಾಮಾಲಾ ಸಮುದಾಯ — ಮಾದರಿ','ಇದು ಕ್ಯಾಲೆಂಡರ್ ಪ್ರದರ್ಶನಕ್ಕಾಗಿ ಸೇರಿಸಿದ ಮಾದರಿ ಕಾರ್ಯಕ್ರಮ. ಇದು ನೈಜ ಕಾರ್ಯಕ್ರಮದ ಆಹ್ವಾನವಲ್ಲ.',true) on conflict(id) do nothing;
insert into public.posts(id,slug,title_kn,title_en,title_translit,summary_kn,body_html,event_date,event_place,published_at,type,status,thumbnail_url,image_credit,is_seed) values('00000000-0000-4000-8000-000000001000','seed-shravanabelagola-heritage','ಶ್ರವಣಬೆಳಗೊಳ: ಭಕ್ತಿ, ಪರಂಪರೆ ಮತ್ತು ಇತಿಹಾಸದ ಜೀವಂತ ಸಂಗಮ','Shravanabelagola: a living heritage','shravanabelagola shravana belagola bahubali','ಬೆಟ್ಟದ ಮೇಲಿನ ಬಾಹುಬಲಿಯ ಸನ್ನಿಧಿಯಿಂದ ಬಸದಿಗಳ ಶಿಲ್ಪಕಲೆಯವರೆಗೆ — ನಮ್ಮ ಜೈನ ಪರಂಪರೆಯನ್ನು ಹತ್ತಿರದಿಂದ ಪರಿಚಯಿಸಿಕೊಳ್ಳೋಣ.','<p>ಬೆಟ್ಟದ ಮೇಲಿನ ಬಾಹುಬಲಿಯ ಸನ್ನಿಧಿಯಿಂದ ಬಸದಿಗಳ ಶಿಲ್ಪಕಲೆಯವರೆಗೆ — ನಮ್ಮ ಜೈನ ಪರಂಪರೆಯನ್ನು ಹತ್ತಿರದಿಂದ ಪರಿಚಯಿಸಿಕೊಳ್ಳೋಣ.</p><p>ನಮ್ಮ ಸಮುದಾಯದ ಪರಂಪರೆ, ನಂಬಿಕೆ ಮತ್ತು ಜೀವನಮೌಲ್ಯಗಳನ್ನು ಪರಿಚಯಿಸುವ ಮಾದರಿ ಲೇಖನ ಇದು. ಈ ಪುಟದ ಮೂಲಕ ಸುದ್ದಿ ಓದುವ ಅನುಭವ, ಕಾರ್ಯಕ್ರಮದ ದಿನಾಂಕ ಮತ್ತು ಸಂಬಂಧಿತ ವಿಷಯಗಳನ್ನು ಪರಿಶೀಲಿಸಬಹುದು.</p><h2>ಪರಂಪರೆಯೊಂದಿಗೆ ಮುಂದಿನ ಹೆಜ್ಜೆ</h2><p>ಜೈನ ಸಂಸ್ಕೃತಿಯಲ್ಲಿ ಅಹಿಂಸೆ, ಸಹಬಾಳ್ವೆ ಮತ್ತು ಸೇವೆಗೆ ವಿಶೇಷ ಸ್ಥಾನವಿದೆ. ನಮ್ಮ ಊರುಗಳ ಇತಿಹಾಸ ಮತ್ತು ಸಮಾಜದ ಸಾಧನೆಗಳನ್ನು ದಾಖಲಿಸುವುದು ಮುಂದಿನ ಪೀಳಿಗೆಗೆ ಅಮೂಲ್ಯ ಕೊಡುಗೆ.</p><p>ಇಲ್ಲಿರುವ ವಿಷಯವು ವಿನ್ಯಾಸವನ್ನು ಪ್ರದರ್ಶಿಸಲು ಸಿದ್ಧಪಡಿಸಿದ ಮಾದರಿ ಮಾತ್ರ. ನೈಜ ವರದಿ ಮತ್ತು ಕಾರ್ಯಕ್ರಮಗಳ ಮಾಹಿತಿಯನ್ನು ಸಂಪಾದಕೀಯ ಪರಿಶೀಲನೆಯ ನಂತರ ಪ್ರಕಟಿಸಲಾಗುತ್ತದೆ.</p>','2026-09-14','ಶ್ರವಣಬೆಳಗೊಳ','2026-09-16T06:30:00Z','article','published','/images/hill.webp','ಮಾದರಿ ಚಿತ್ರ',true) on conflict(id) do nothing;
