insert into public.posts(id,slug,title_kn,title_en,title_translit,summary_kn,body_html,event_date,event_place,published_at,type,status,thumbnail_url,image_credit,is_seed) values('00000000-0000-4000-8000-000000001012','seed-chaturmasa-reflections-archive','ಚಾತುರ್ಮಾಸ: ಆತ್ಮಚಿಂತನೆ ಮತ್ತು ಅಹಿಂಸೆಯ ಹಾದಿಯಲ್ಲಿ','Chaturmasa reflections on ahimsa','chaturmasa ahimsa pravachana','ನಿತ್ಯ ಜೀವನದಲ್ಲಿ ಸಂಯಮ, ಕರುಣೆ ಮತ್ತು ಸರಳತೆಯ ಮಹತ್ವವನ್ನು ತಿಳಿಸುವ ಚಿಂತನೆಗಳು.','<p>ನಿತ್ಯ ಜೀವನದಲ್ಲಿ ಸಂಯಮ, ಕರುಣೆ ಮತ್ತು ಸರಳತೆಯ ಮಹತ್ವವನ್ನು ತಿಳಿಸುವ ಚಿಂತನೆಗಳು.</p><p>ನಮ್ಮ ಸಮುದಾಯದ ಪರಂಪರೆ, ನಂಬಿಕೆ ಮತ್ತು ಜೀವನಮೌಲ್ಯಗಳನ್ನು ಪರಿಚಯಿಸುವ ಮಾದರಿ ಲೇಖನ ಇದು. ಈ ಪುಟದ ಮೂಲಕ ಸುದ್ದಿ ಓದುವ ಅನುಭವ, ಕಾರ್ಯಕ್ರಮದ ದಿನಾಂಕ ಮತ್ತು ಸಂಬಂಧಿತ ವಿಷಯಗಳನ್ನು ಪರಿಶೀಲಿಸಬಹುದು.</p><h2>ಪರಂಪರೆಯೊಂದಿಗೆ ಮುಂದಿನ ಹೆಜ್ಜೆ</h2><p>ಜೈನ ಸಂಸ್ಕೃತಿಯಲ್ಲಿ ಅಹಿಂಸೆ, ಸಹಬಾಳ್ವೆ ಮತ್ತು ಸೇವೆಗೆ ವಿಶೇಷ ಸ್ಥಾನವಿದೆ. ನಮ್ಮ ಊರುಗಳ ಇತಿಹಾಸ ಮತ್ತು ಸಮಾಜದ ಸಾಧನೆಗಳನ್ನು ದಾಖಲಿಸುವುದು ಮುಂದಿನ ಪೀಳಿಗೆಗೆ ಅಮೂಲ್ಯ ಕೊಡುಗೆ.</p><p>ಇಲ್ಲಿರುವ ವಿಷಯವು ವಿನ್ಯಾಸವನ್ನು ಪ್ರದರ್ಶಿಸಲು ಸಿದ್ಧಪಡಿಸಿದ ಮಾದರಿ ಮಾತ್ರ. ನೈಜ ವರದಿ ಮತ್ತು ಕಾರ್ಯಕ್ರಮಗಳ ಮಾಹಿತಿಯನ್ನು ಸಂಪಾದಕೀಯ ಪರಿಶೀಲನೆಯ ನಂತರ ಪ್ರಕಟಿಸಲಾಗುತ್ತದೆ.</p>','2026-09-08','ಹಾಸನ','2026-09-12T06:30:00Z','video','published','/images/detail.webp','ಮಾದರಿ ಚಿತ್ರ',true) on conflict(id) do nothing;
